data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))

def preorder(order):
    L = {}
    R = {}
    root = order[0]
    for v in order[1:]:
        cur = root
        while True:
            if v < cur:
                if cur in L:
                    cur = L[cur]
                else:
                    L[cur] = v
                    break
            else:
                if cur in R:
                    cur = R[cur]
                else:
                    R[cur] = v
                    break
    out = []
    st = [root]
    while st:
        u = st.pop()
        out.append(u)
        if u in R:
            st.append(R[u])
        if u in L:
            st.append(L[u])
    return out

