    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    def balanced_order(vals):
        vals = sorted(vals)
        order = []
        q = [(0, len(vals))]
        i = 0
        while i < len(q):
            lo, hi = q[i]
            i += 1
            if lo >= hi:
                continue
            mid = (lo + hi) // 2
            order.append(vals[mid])
            q.append((lo, mid))
            q.append((mid + 1, hi))
        return order
    tests = [fmt([5]), fmt([2, 1, 3]), fmt([1, 2]), fmt([2, 1]), fmt([1, 2, 3, 4]), fmt([4, 3, 2, 1]), fmt([4, 1, 3, 2, 5, 7, 6, 8, 11, 10]), fmt([3, 1, 2, 5, 4]), fmt([10, 5, 3, 7, 15, 12, 20])]
